def filter_dict_by_value(dictionary, threshold):
    return {k: v for k, v in dictionary.items() if v > threshold}

sample_dict = {'a': 1, 'b': 2, 'c': 3, 'd': 4}
print(filter_dict_by_value(sample_dict, 2))  # Output: {'c': 3, 'd': 4}

